def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    paths = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                cells = [(r, c), (r, c+1), (r, c+2), (r-1, c+2), (r, c)]
                ends = [(r, c), (r-1, c+2)]
            elif color == 2:
                cells = [(r, x) for x in range(c-4, c+1)]
                ends = [(r, c-4), (r, c)]
            elif color == 3:
                cells = [(x, c) for x in range(r, r+4)]
                ends = [(r, c), (r+3, c)]
            elif color == 6:
                cells = [(x, c) for x in range(r-6, r+1)]
                ends = [(r-6, c), (r, c)]
            else:
                continue
            paths.append((color, cells, ends))

    # Count path memberships to identify line crossings.
    memberships = {}
    endpoint_colors = {}
    for color, cells, ends in paths:
        for p in cells:
            if 0 <= p[0] < h and 0 <= p[1] < w:
                memberships.setdefault(p, set()).add(color)
        for p in ends:
            if 0 <= p[0] < h and 0 <= p[1] < w:
                endpoint_colors[p] = color
    for p, colors in memberships.items():
        r, c = p
        if p in endpoint_colors:
            out[r][c] = endpoint_colors[p]
        elif len(colors) > 1:
            out[r][c] = 4
        else:
            out[r][c] = 5
    return out
